<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {ArrowRight,CalendarClock,Check,Edit3,Pause,Play,Plus,RefreshCw,ShieldCheck,Trash2,X} from 'lucide-vue-next'
import {request} from '../api'
import type {Account,Job} from '../types'
const props=defineProps<{accounts:Account[];demo:boolean;runAccountID?:string;requestToken?:number}>()
const emit=defineEmits<{refresh:[];configure:[id:string,mode:string]}>()
type Entry={id:string;account_id:string;name:string;enabled:boolean;hour:number;minute:number;weekdays:number[];timezone:string;next_run_at:string}
const runType=ref('daily')
const entries=ref<Entry[]>([]),jobs=ref<Job[]>([]),busy=ref(false),error=ref(''),message=ref(''),resolveID=ref(''),editingID=ref('')
const form=ref({account_id:props.accounts[0]?.id||'',name:'每日挂机',time:'09:00',weekdays:[1,2,3,4,5,6,0],enabled:true}),runAccount=ref(props.runAccountID||props.accounts[0]?.id||'')
const days=[{id:1,name:'一'},{id:2,name:'二'},{id:3,name:'三'},{id:4,name:'四'},{id:5,name:'五'},{id:6,name:'六'},{id:0,name:'日'}]
const labels:Record<string,string>={pending:'已排队',dispatched:'等待 Windows',waiting:'等待 MAA 空闲',starting:'正在准备配置档',running:'正在执行',stopping:'等待停止确认',completed:'队列完成',completed_with_errors:'结束但有错误',failed:'执行失败',cancelled:'已取消 / 停止',expired:'已错过执行窗口',unknown:'结果待核实'}
const accountName=(id:string)=>props.accounts.find(a=>a.id===id)?.name||id
const date=(v:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'—'
const active=computed(()=>jobs.value.filter(j=>['pending','dispatched','waiting','starting','running','stopping','unknown'].includes(j.state)))
const native=computed(()=>props.accounts.flatMap(a=>(a.instance?.native_timers||[]).filter(t=>t.profile_id===a.profile?.id).map(t=>({...t,account:a}))))
function weekdayLabel(v:number[]){return v.length===7?'每天':v.length===5&&[1,2,3,4,5].every(n=>v.includes(n))?'工作日':`每周${days.filter(d=>v.includes(d.id)).map(d=>d.name).join('、')}`}
function reset(){editingID.value='';form.value={account_id:props.accounts[0]?.id||'',name:'每日挂机',time:'09:00',weekdays:[1,2,3,4,5,6,0],enabled:true}}
function edit(e:Entry){editingID.value=e.id;form.value={account_id:e.account_id,name:e.name,time:`${String(e.hour).padStart(2,'0')}:${String(e.minute).padStart(2,'0')}`,weekdays:[...e.weekdays],enabled:e.enabled};document.querySelector('.scheduler-form')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{if(props.demo){message.value='演示模式不创建实际计划或执行游戏任务。';return}await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){if(props.demo)return;try{const [s,j]=await Promise.all([request<Entry[]>('/schedules'),request<Job[]>('/jobs')]);entries.value=s;jobs.value=j}catch(e){error.value=(e as Error).message}}
async function save(){await run(async()=>{const [hour,minute]=form.value.time.split(':').map(Number);if(!form.value.weekdays.length)throw Error('请至少选择一个星期');await request(editingID.value?`/schedules/${editingID.value}`:'/schedules',{method:editingID.value?'PUT':'POST',body:JSON.stringify({...form.value,hour,minute,timezone:'Asia/Shanghai'})});reset();await load();emit('refresh');message.value='定时计划已保存。到点后自动排队，同一 Windows 设备串行执行。'})}
async function toggle(e:Entry){await run(async()=>{await request(`/schedules/${e.id}`,{method:'PUT',body:JSON.stringify({...e,enabled:!e.enabled})});await load()})}
async function remove(e:Entry){await run(async()=>{await request(`/schedules/${e.id}`,{method:'DELETE'});await load();message.value='已删除后续定时。已排队的任务仍可在执行队列中取消。'})}
async function start(){await run(async()=>{await request('/jobs',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({account_id:runAccount.value,type:runType.value})});await load();emit('refresh');message.value='已加入真实执行队列，请查看下方 Windows 回执。'})}
async function stop(j:Job){await run(async()=>{await request(`/jobs/${j.id}/cancel`,{method:'POST',body:'{}'});await load();message.value=j.state==='pending'?'已取消排队任务。':'已请求停止，实际状态以 Windows 回执为准。'})}
async function resolve(j:Job){await run(async()=>{await request(`/jobs/${j.id}/resolve`,{method:'POST',body:JSON.stringify({confirm:j.id})});resolveID.value='';await load();message.value='已请求 Windows 确认空闲并解除占用，不会重新启动该任务。'})}
let timer:ReturnType<typeof setInterval>
watch(()=>props.requestToken,()=>{if(props.runAccountID)runAccount.value=props.runAccountID;document.querySelector('.scheduler-run')?.scrollIntoView({behavior:'smooth',block:'center'})})
onMounted(()=>{load();timer=setInterval(load,5000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template>
<div class="scheduler-workspace">
<p class="inline-alert" v-if="error" role="alert">{{error}}</p><p class="agent-feedback" v-if="message" role="status"><Check :size="16"/>{{message}}</p>
<div class="scheduler-grid"><section class="panel scheduler-form"><div class="panel-heading"><div><span class="eyebrow">// EACH ACCOUNT, ITS OWN ROUTINE</span><h2>{{editingID?'编辑定时计划':'添加定时计划'}}</h2></div><CalendarClock :size="22"/></div><form @submit.prevent="save"><label>执行账号<select v-model="form.account_id" required :disabled="!!editingID"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}} · {{a.profile?.name||'未绑定'}}</option></select></label><label>计划名称<input v-model="form.name" maxlength="120" required/></label><div class="scheduler-fields"><label>执行时间 · 北京时间<input v-model="form.time" type="time" required/></label><label class="scheduler-check"><input type="checkbox" v-model="form.enabled"/>启用此计划</label></div><fieldset><legend>每周执行日</legend><div class="weekdays"><label v-for="d in days" :key="d.id" :class="{chosen:form.weekdays.includes(d.id)}"><input type="checkbox" :value="d.id" v-model="form.weekdays"/><span>{{d.name}}</span></label></div></fieldset><div class="info-strip"><ShieldCheck :size="16"/><span>执行所选配置档中已启用的任务，并按开始唤醒设置切换游戏账号。共用 Windows / 模拟器时顺序执行。</span></div><div class="agent-button-row"><button class="button primary" :disabled="busy||!form.account_id"><Plus :size="16"/>{{editingID?'保存修改':'创建真实定时计划'}}<ArrowRight :size="16"/></button><button v-if="editingID" class="button" type="button" @click="reset"><X :size="15"/>取消编辑</button></div></form></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">// SCHEDULES</span><h2>账号定时 <small>{{entries.length}}</small></h2></div><button class="text-button" @click="load"><RefreshCw :size="15"/>刷新</button></div><div class="scheduler-empty" v-if="!entries.length">还没有网页定时计划。添加后会显示下一次执行时间。</div><article class="schedule-row" v-for="e in entries" :key="e.id"><div class="schedule-time"><strong>{{String(e.hour).padStart(2,'0')}}:{{String(e.minute).padStart(2,'0')}}</strong><span class="agent-chip">{{e.enabled?'已启用':'已暂停'}}</span></div><h3>{{e.name}}</h3><p>{{accountName(e.account_id)}} · {{weekdayLabel(e.weekdays)}}</p><small>{{e.enabled?`下次执行：${date(e.next_run_at)}`:'暂停期间不生成新任务'}}</small><div class="agent-button-row"><button class="text-button" :disabled="busy" @click="toggle(e)"><Pause v-if="e.enabled" :size="14"/><Play v-else :size="14"/>{{e.enabled?'暂停':'启用'}}</button><button class="text-button" :disabled="busy" @click="edit(e)"><Edit3 :size="14"/>编辑</button><button class="text-button" :disabled="busy" @click="remove(e)"><Trash2 :size="14"/>删除</button></div></article></section></div>
<section class="panel scheduler-run"><div class="panel-heading"><div><span class="eyebrow">// RUN NOW</span><h2>立即执行</h2></div><Play :size="21"/></div><form class="scheduler-run-form" @submit.prevent="start"><label>执行账号<select v-model="runAccount" required><option v-for="a in accounts" :value="a.id" :key="a.id">{{a.name}} · {{a.profile?.name||'未绑定'}}</option></select></label><label>执行方式<select v-model="runType"><option value="daily">运行已启用的游戏任务</option><option value="check">仅检查配置切换与 MAA 界面</option></select></label><button class="button primary" :disabled="busy||!runAccount"><Play :size="16"/>{{runType==='check'?'检查配置档切换':'执行当前配置'}}</button><p class="muted">{{runType==='check'?'仅切换 MAA 配置档并检查空闲界面，不启动游戏任务，也不验证游戏内登录结果。':'这会实际操作游戏，使用该配置当前启用的任务与资源预算。需要调整任务或库存目标时，先到配置编辑保存。'}}</p></form></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">// REAL EXECUTION RECEIPTS</span><h2>执行队列与历史 <small>{{active.length}} 项待处理</small></h2></div><button class="text-button" @click="load"><RefreshCw :size="15"/>刷新</button></div><div class="scheduler-empty" v-if="!jobs.length">尚无网页下发的任务。这里显示真实任务记录，不使用模拟进度。</div><article class="execution-row" v-for="j in jobs" :key="j.id"><div><div class="execution-title"><strong>{{accountName(j.account_id)}} · {{j.type==='check'?'配置切换检查':'日常任务'}}</strong><span class="agent-chip" :class="{running:j.state==='running',failure:['failed','unknown','completed_with_errors'].includes(j.state)}">{{labels[j.state]||j.state}}</span></div><p>{{j.detail}}</p><small>{{date(j.created_at)}} · {{j.schedule_id?'定时触发':'手动触发'}}</small></div><button v-if="['pending','dispatched','waiting','starting','running'].includes(j.state)" class="button small" :disabled="busy" @click="stop(j)"><Pause :size="14"/>{{j.state==='pending'?'取消排队':'请求停止'}}</button><button v-if="j.state==='unknown'&&resolveID!==j.id" class="text-button" @click="resolveID=j.id">核实并解除占用</button><div v-if="resolveID===j.id" class="scheduler-resolution"><p>请先检查 MAA 当前任务。Windows 只会在确认空闲后释放该任务占用，不会重跑。</p><div class="agent-button-row"><button class="button" @click="resolveID=''">返回</button><button class="button primary" :disabled="busy" @click="resolve(j)">已核实，请求释放</button></div></div></article></section>
<section class="panel native-schedules" v-if="native.length"><div class="panel-heading"><div><span class="eyebrow">// EXISTING MAA TIMERS</span><h2>原有 MAA 定时</h2></div><CalendarClock :size="21"/></div><p class="scheduler-note">原有安排继续由 MAA 执行。启用的强制定时可能打断网页任务或切换配置；建议先在配置编辑中核对、调整重叠时间，再创建新计划。</p><div class="native-row" v-for="t in native" :key="`${t.account.id}-${t.id}`"><span>{{t.account.name}} · {{String(t.hour).padStart(2,'0')}}:{{String(t.minute).padStart(2,'0')}}</span><span class="muted">{{t.enabled?'MAA中已启用':'未启用'}}</span><button class="text-button" @click="emit('configure',t.account.id,'timers')">调整原有定时<ArrowRight :size="14"/></button></div></section>
</div>
</template>
<style scoped>
.scheduler-workspace{--line:var(--ef-rule);--surface:var(--ef-panel);--bg:var(--ef-paper);--text:var(--ef-ink);--muted:var(--ef-ink-2)}.scheduler-workspace>.panel{margin-top:24px}.scheduler-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px}.panel{border:1px solid var(--line);background:var(--surface);min-width:0}.panel-heading{display:flex;gap:18px;align-items:center;justify-content:space-between;padding:22px 24px;border-bottom:1px solid var(--line)}.panel-heading h2{margin-top:5px}.panel-heading small{font-weight:400;color:var(--muted);margin-left:8px}.scheduler-form form{padding:24px;display:grid;gap:21px}.scheduler-workspace label{display:flex;flex-direction:column;gap:9px;font-size:12px}.scheduler-workspace input:not([type=checkbox]),.scheduler-workspace select{border:1px solid var(--line);background:var(--bg);color:var(--text);min-height:42px;padding:10px 12px;min-width:0;width:100%;border-radius:0;font:inherit}.scheduler-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:center}.scheduler-workspace .scheduler-check{display:flex;flex-direction:row;gap:10px;align-items:center}.scheduler-check input{width:16px;height:16px;accent-color:var(--yellow)}fieldset{padding:0;border:0;margin:0;min-width:0}legend{font-size:12px;margin-bottom:10px}.weekdays{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}.weekdays label{display:grid;place-items:center;position:relative;border:1px solid var(--line);height:40px;cursor:pointer}.weekdays input{position:absolute;opacity:0;width:100%;height:100%;margin:0;cursor:pointer}.weekdays .chosen{background:var(--yellow);color:#151515;border-color:var(--yellow)}.scheduler-form .info-strip{margin:0}.schedule-row{padding:22px 24px;border-bottom:1px solid var(--line)}.schedule-row:last-child{border:0}.schedule-time{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.schedule-time strong{font-family:Saira,sans-serif;font-size:31px;line-height:1}.schedule-row h3{font-size:14px}.schedule-row p,.schedule-row small{display:block;margin:7px 0;color:var(--muted);font-size:12px}.schedule-row .agent-button-row{margin-top:12px;gap:18px}.scheduler-empty{padding:30px 24px;color:var(--muted);line-height:1.9}.scheduler-run-form{display:flex;align-items:end;flex-wrap:wrap;gap:18px;padding:24px}.scheduler-run-form>label{flex:1;min-width:220px}.scheduler-run-form>p{width:100%;margin:0}.execution-row{padding:20px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap}.execution-row>div:first-child{flex:1;min-width:220px}.execution-title{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.execution-row p{font-size:12px;margin:12px 0;color:var(--muted);line-height:1.8}.execution-row small{font-size:10px;color:var(--muted)}.execution-row .agent-chip.running{border-color:var(--yellow);background:var(--yellow);color:#151515}.failure{border-left:3px solid currentColor}.scheduler-note{padding:20px 24px;margin:0;color:var(--muted);font-size:12px;line-height:1.9}.native-row{display:flex;gap:16px;justify-content:space-between;align-items:center;padding:13px 24px;border-top:1px solid var(--line);font-size:12px;flex-wrap:wrap}.scheduler-resolution{width:100%;padding:18px;background:var(--bg);border:1px solid var(--line)}@media(max-width:1000px){.scheduler-grid{grid-template-columns:1fr}}@media(max-width:600px){.panel-heading,.schedule-row,.scheduler-form form,.scheduler-run-form,.execution-row{padding:20px}.execution-title{gap:10px}.scheduler-fields{grid-template-columns:1fr}.weekdays{gap:4px}.weekdays label{height:38px}.scheduler-run-form>label{min-width:0;width:100%;flex:0 0 100%}.scheduler-run-form .button{width:100%}.execution-row>div:first-child{min-width:0;width:100%;flex:auto}.native-row{padding:16px 20px}}
</style>
